# ! [doc = " Implementation of panics backed by libgcc/libunwind (in some form)."] # ! [doc = ""] # ! [doc = " For background on exception handling and stack unwinding please see"] # ! [doc = " \"Exception Handling in LLVM\" (llvm.org/docs/ExceptionHandling.html) and"] # ! [doc = " documents linked from it."] # ! [doc = " These are also good reads:"] # ! [doc = "  * <https://itanium-cxx-abi.github.io/cxx-abi/abi-eh.html>"] # ! [doc = "  * <https://nicolasbrailo.github.io/blog/projects_texts/13exceptionsunderthehood.html>"] # ! [doc = "  * <https://www.airs.com/blog/index.php?s=exception+frames>"] # ! [doc = ""] # ! [doc = " ## A brief summary"] # ! [doc = ""] # ! [doc = " Exception handling happens in two phases: a search phase and a cleanup"] # ! [doc = " phase."] # ! [doc = ""] # ! [doc = " In both phases the unwinder walks stack frames from top to bottom using"] # ! [doc = " information from the stack frame unwind sections of the current process's"] # ! [doc = " modules (\"module\" here refers to an OS module, i.e., an executable or a"] # ! [doc = " dynamic library)."] # ! [doc = ""] # ! [doc = " For each stack frame, it invokes the associated \"personality routine\", whose"] # ! [doc = " address is also stored in the unwind info section."] # ! [doc = ""] # ! [doc = " In the search phase, the job of a personality routine is to examine"] # ! [doc = " exception object being thrown, and to decide whether it should be caught at"] # ! [doc = " that stack frame. Once the handler frame has been identified, cleanup phase"] # ! [doc = " begins."] # ! [doc = ""] # ! [doc = " In the cleanup phase, the unwinder invokes each personality routine again."] # ! [doc = " This time it decides which (if any) cleanup code needs to be run for"] # ! [doc = " the current stack frame. If so, the control is transferred to a special"] # ! [doc = " branch in the function body, the \"landing pad\", which invokes destructors,"] # ! [doc = " frees memory, etc. At the end of the landing pad, control is transferred"] # ! [doc = " back to the unwinder and unwinding resumes."] # ! [doc = ""] # ! [doc = " Once stack has been unwound down to the handler frame level, unwinding stops"] # ! [doc = " and the last personality routine transfers control to the catch block."] use split_decls_genesis :: ourprelude :: * ; use alloc :: boxed :: Box ; use core :: any :: Any ; use core :: ptr ; use unwind as uw ; static CANARY : u8 = 0 ; #[repr (C)] struct Exception { _uwe : uw :: _Unwind_Exception , canary : * const u8 , cause : Box < dyn Any + Send > , } pub (crate) unsafe fn panic (data : Box < dyn Any + Send >) -> u32 { let exception = Box :: new (Exception { _uwe : uw :: _Unwind_Exception { exception_class : RUST_EXCEPTION_CLASS , exception_cleanup : Some (exception_cleanup) , private : [core :: ptr :: null () ; uw :: unwinder_private_data_size] , } , canary : & CANARY , cause : data , }) ; let exception_param = Box :: into_raw (exception) as * mut uw :: _Unwind_Exception ; return unsafe { uw :: _Unwind_RaiseException (exception_param) as u32 } ; extern "C" fn exception_cleanup (_unwind_code : uw :: _Unwind_Reason_Code , exception : * mut uw :: _Unwind_Exception ,) { unsafe { let _ : Box < Exception > = Box :: from_raw (exception as * mut Exception) ; super :: __rust_drop_panic () ; } } } pub (crate) unsafe fn cleanup (ptr : * mut u8) -> Box < dyn Any + Send > { unsafe { let exception = ptr as * mut uw :: _Unwind_Exception ; if (* exception) . exception_class != RUST_EXCEPTION_CLASS { uw :: _Unwind_DeleteException (exception) ; super :: __rust_foreign_exception () ; } let exception = exception . cast :: < Exception > () ; let canary = (& raw const (* exception) . canary) . read () ; if ! ptr :: eq (canary , & CANARY) { super :: __rust_foreign_exception () ; } let exception = Box :: from_raw (exception as * mut Exception) ; exception . cause } } const RUST_EXCEPTION_CLASS : uw :: _Unwind_Exception_Class = u64 :: from_ne_bytes (* b"MOZ\0RUST") ;